-- Prolog Hari 0 (Kedatangan). Digenerate dari day0_kedatangan_vn_v2.md — edit Tools/gen_day0_prologue.py lalu generate ulang.
DELETE FROM tbl_dialogue_options WHERE node_id BETWEEN 9000 AND 9999 OR node_id BETWEEN 10001 AND 10005;
DELETE FROM tbl_dialogue_nodes WHERE node_id BETWEEN 9000 AND 9999 OR node_id BETWEEN 10001 AND 10005;
INSERT INTO tbl_dialogue_nodes (node_id, dialogue_id, dialogue_code, speaker_name, dialogue_text, character_sprite_path, next_dialogue_id, has_options, npc_id, req_language, req_etiquette, priority) VALUES
(9001, 9001, 'D_PROLOGUE_01', '', 'Gerbang kampus lebih besar dari yang kubayangkan dari foto-foto di email penerimaan. Dua pilar batu, ukiran aksara yang tidak bisa kubaca, dan satu papan nama panjang yang hanya kukenali huruf romannya di baris paling bawah.', '', 9002, 0, 0, 0, 0, 10),
(9002, 9002, 'D_PROLOGUE_9002', '', 'Koperku berhenti di celah ubin, roda kirinya nyangkut entah kenapa. Selalu begitu. Kalau ada satu celah di sepuluh meter persegi ubin, roda koperku akan menemukannya.', '', 9003, 0, 0, 0, 0, 10),
(9003, 9003, 'D_PROLOGUE_9003', '', 'Aku menariknya lagi, lebih keras. Tas kamera di bahu kananku ikut bergoyang, dan aku refleks menahannya dengan siku. Kebiasaan lama. Barang itu lebih penting dari koper. Kalau dipikir-pikir, aneh juga urutan prioritasku.', '', 9004, 0, 0, 0, 0, 10),
(9004, 9004, 'D_PROLOGUE_9004', '', 'Orang-orang lewat begitu saja. Tidak ada yang menoleh, tidak ada yang perlu menoleh.', '', 9005, 0, 0, 0, 0, 10),
(9005, 9005, 'D_PROLOGUE_9005', '', 'Di pesawat tadi aku sempat menghafal beberapa kalimat dari aplikasi belajar bahasa. <i>Nǐ hǎo.</i> <i>Xièxie.</i> <i>Bù hǎo yìsi.</i> <i>Bú duì.</i> Ditambah angka satu sampai sepuluh. Aku belum yakin bisa mengucapkan satu pun dengan benar.', '', 9006, 0, 0, 0, 0, 10),
(9006, 9006, 'D_PROLOGUE_9006', '', 'Aku mengeluarkan kertas konfirmasi asrama dari saku jaket. Gedung C, kamar 503. Kucocokkan dengan papan penunjuk yang setengahnya berbahasa Mandarin, setengahnya bahasa Inggris yang terjemahannya terasa dipaksakan.', '', 9007, 0, 0, 0, 0, 10),
(9007, 9007, 'D_PROLOGUE_9007', '', 'Belum sempat aku memutuskan arah, ada suara yang memecah semuanya.', '', 9008, 0, 0, 0, 0, 10),
(9008, 9008, 'D_PROLOGUE_9008', '???', 'DEVANO?!', '', 9009, 0, 0, 0, 0, 10),
(9009, 9009, 'D_PROLOGUE_9009', '', 'Seseorang berlari kecil dari arah pos satpam. Kuncir dua bergelombangnya memantul-mantul, satu tangan melambai terlalu semangat untuk ukuran sore yang sepi begini. Dia berhenti tepat di depanku, agak terengah, lalu buru-buru merapikan napas seolah baru sadar dia barusan lari.', 'Assets/Character/Edelweiss/Edelweiss.png', 9010, 0, 0, 0, 0, 10),
(9010, 9010, 'D_PROLOGUE_9010', '???', 'Kamu Devano kan? Dari Indonesia?', 'Assets/Character/Edelweiss/Edelweiss.png', 9011, 0, 0, 0, 0, 10),
(9011, 9011, 'D_PROLOGUE_9011', 'Pilihan', 'Sapaan', 'Assets/Character/Edelweiss/Edelweiss.png', 0, 1, 0, 0, 0, 10),
(9012, 9012, 'D_PROLOGUE_9012', '', 'Dia mengeluarkan sesuatu dari saku pinaforenya, gerakannya refleks, seperti sudah ratusan kali dilakukan. Sebungkus permen kecil.', 'Assets/Character/Edelweiss/Edelweiss.png', 9013, 0, 0, 0, 0, 10),
(9013, 9013, 'D_PROLOGUE_9013', 'Edelweiss', 'Nih. Buat penyambutan.', 'Assets/Character/Edelweiss/Edelweiss.png', 9014, 0, 2, 0, 0, 10),
(9014, 9014, 'D_PROLOGUE_9014', '', 'Dia menyodorkannya dengan senyum lebar, lalu cepat-cepat menambahkan,', 'Assets/Character/Edelweiss/Edelweiss.png', 9015, 0, 0, 0, 0, 10),
(9015, 9015, 'D_PROLOGUE_9015', 'Edelweiss', 'Semua orang baru kukasih ini kok, bukan cuma kamu doang.', 'Assets/Character/Edelweiss/Edelweiss.png', 9016, 0, 2, 0, 0, 10),
(9016, 9016, 'D_PROLOGUE_9016', 'Pilihan', 'Permen', 'Assets/Character/Edelweiss/Edelweiss.png', 0, 1, 0, 0, 0, 10),
(9017, 9017, 'D_PROLOGUE_9017', '', 'Dia menepuk kedua tangannya dan berbalik badan.', 'Assets/Character/Edelweiss/Edelweiss.png', 9018, 0, 0, 0, 0, 10),
(9018, 9018, 'D_PROLOGUE_9018', 'Edelweiss', 'Yaudah, ayo! Gedung C di sebelah sana. Agak jauh dikit, tapi santai aja jalan kaki.', 'Assets/Character/Edelweiss/Edelweiss.png', 9019, 0, 2, 0, 0, 10),
(9019, 9019, 'D_PROLOGUE_9019', '', 'Aku mengikutinya. Langkahnya lebih cepat dari orang yang sedang jalan santai, seperti ada energi yang perlu disalurkan ke suatu tempat. Dia ramah, tapi ramahnya punya kecepatan sendiri. Seolah kalau dia berhenti sedetik saja, sesuatu yang lain bakal kelihatan.', '', 9020, 0, 0, 0, 0, 10),
(9020, 9020, 'D_PROLOGUE_9020', '', 'Jalan menuju asrama melewati deretan pohon yang belum kukenal namanya, lalu kantin yang lampunya baru menyala satu per satu, lalu papan pengumuman penuh kertas warna-warni yang sebagian sudah sobek di ujung.', '', 9021, 0, 0, 0, 0, 10),
(9021, 9021, 'D_PROLOGUE_9021', '', 'Aku belum sempat memotret apa pun, tapi mataku sudah bekerja sendiri, menyusun komposisi. Siluet gedung asrama dengan lampu koridor yang menyala bergiliran. Lebih menarik daripada gedungnya sendiri.', '', 9022, 0, 0, 0, 0, 10),
(9022, 9022, 'D_PROLOGUE_9022', '', 'Edelweiss melirik ke arahku. Langkahnya melambat, menyesuaikan langkahku yang masih menyeret koper.', 'Assets/Character/Edelweiss/Edelweiss.png', 9023, 0, 0, 0, 0, 10),
(9023, 9023, 'D_PROLOGUE_9023', 'Edelweiss', 'Kamu excited nggak? Sebulan doang kan di sini?', 'Assets/Character/Edelweiss/Edelweiss.png', 9024, 0, 2, 0, 0, 10),
(9024, 9024, 'D_PROLOGUE_9024', 'Pilihan', 'Perasaan', 'Assets/Character/Edelweiss/Edelweiss.png', 0, 1, 0, 0, 0, 10),
(9025, 9025, 'D_PROLOGUE_9025', 'Edelweiss', 'Ih, nanti kutunjukin spot-spot bagus deh. Aku udah lama di sini soalnya.', 'Assets/Character/Edelweiss/Edelweiss.png', 9026, 0, 2, 0, 0, 10),
(9026, 9026, 'D_PROLOGUE_9026', 'Devano', 'Boleh.', '', 9027, 0, 0, 0, 0, 10),
(9027, 9027, 'D_PROLOGUE_9027', '', 'Untuk pertama kalinya sejak turun dari bandara, ada sesuatu yang terasa sedikit lebih ringan.', '', 9028, 0, 0, 0, 0, 10),
(9028, 9028, 'D_PROLOGUE_9028', '', 'Lobi Gedung C lebih ramai dari yang kukira. Ada antrean pendek di depan meja kayu dekat pintu masuk: tiga atau empat mahasiswa dengan koper, beberapa sambil main ponsel, satu sambil makan sesuatu dari kantong plastik.', '', 9029, 0, 0, 0, 0, 10),
(9029, 9029, 'D_PROLOGUE_9029', '', 'Di balik meja duduk seorang ibu paruh baya dengan rompi rajut dan kacamata yang melorot ke ujung hidung. Di sebelahnya ada termos besar, buku catatan tebal, dan papan berisi deretan kunci.', '', 9030, 0, 0, 0, 0, 10),
(9030, 9030, 'D_PROLOGUE_9030', 'Edelweiss', '(berbisik) Itu 阿姨, ibu pengelola asrama. Panggil aja <i>Āyí</i>. Semua urusan asrama lewat dia.', 'Assets/Character/Edelweiss/Edelweiss.png', 9031, 0, 2, 0, 0, 10),
(9031, 9031, 'D_PROLOGUE_9031', '', 'Antrean maju. Giliranku.', '', 9032, 0, 0, 0, 0, 10),
(9032, 9032, 'D_PROLOGUE_9032', 'Āyí', '护照。
<size=80%><i>Hùzhào. — "Paspor."</i></size>', '', 9033, 0, 0, 0, 0, 10),
(9033, 9033, 'D_PROLOGUE_9033', '', 'Aku menyerahkan paspor. Dia membolak-baliknya, menulis sesuatu di buku catatannya dengan cepat, lalu mengambil satu kunci dari papan dan meletakkannya di meja bersama kartu kecil.', '', 9034, 0, 0, 0, 0, 10),
(9034, 9034, 'D_PROLOGUE_9034', 'Āyí', '三零五。
<size=80%><i>Sān líng wǔ. — "Tiga-nol-lima."</i></size>', '', 9035, 0, 0, 0, 0, 10),
(9035, 9035, 'D_PROLOGUE_9035', '', 'Aku melihat kartu itu. 305. Lalu kertas konfirmasi di tanganku. 503.', '', 9036, 0, 0, 0, 0, 10),
(9036, 9036, 'D_PROLOGUE_9036', '', 'Angkanya kebalik.', '', 9037, 0, 0, 0, 0, 10),
(9037, 9037, 'D_PROLOGUE_9037', '', 'Di belakangku, mahasiswa yang makan dari kantong plastik tadi berhenti mengunyah, menunggu. Aku bisa merasakan antrean itu di punggungku tanpa perlu menoleh.', '', 9038, 0, 0, 0, 0, 10),
(9038, 9038, 'D_PROLOGUE_9038', 'Pilihan', 'Kesalahan Āyí', '', 0, 1, 0, 0, 0, 10),
(9039, 9039, 'D_PROLOGUE_9039', 'Edelweiss', 'Satu lagi. Baik-baikin Āyí. Paket, jam malam, kunci cadangan kalau kamu kekunci, semua lewat dia. Di sini, kenal baik sama orang yang tepat itu lebih kepake daripada hafal peraturan.', 'Assets/Character/Edelweiss/Edelweiss.png', 9040, 0, 2, 0, 0, 10),
(9040, 9040, 'D_PROLOGUE_9040', '', 'Aku menyimpan kalimat itu di kepala, di sebelah <i>bù hǎo yìsi</i>.', 'Assets/Character/Edelweiss/Edelweiss.png', 9041, 0, 0, 0, 0, 10),
(9041, 9041, 'D_PROLOGUE_9041', '', 'Edelweiss berhenti di anak tangga pertama.', 'Assets/Character/Edelweiss/Edelweiss.png', 9042, 0, 0, 0, 0, 10),
(9042, 9042, 'D_PROLOGUE_9042', 'Edelweiss', 'Aku cuma bisa antar sampai sini. Cewek nggak boleh naik.', 'Assets/Character/Edelweiss/Edelweiss.png', 9043, 0, 2, 0, 0, 10),
(9043, 9043, 'D_PROLOGUE_9043', '', 'Aku baru sadar plester di jari telunjukku sudah lepas separuh. Mungkin dari gesekan dengan pegangan koper. Lukanya sudah kering, tidak masalah sebenarnya. Aku baru mau menempelkannya lagi ketika Edelweiss lebih dulu melihat.', 'Assets/Character/Edelweiss/Edelweiss.png', 9044, 0, 0, 0, 0, 10),
(9044, 9044, 'D_PROLOGUE_9044', 'Edelweiss', 'Eh, jarimu kenapa?', 'Assets/Character/Edelweiss/Edelweiss.png', 9045, 0, 2, 0, 0, 10),
(9045, 9045, 'D_PROLOGUE_9045', 'Pilihan', 'Luka', 'Assets/Character/Edelweiss/Edelweiss.png', 0, 1, 0, 0, 0, 10),
(9046, 9046, 'D_PROLOGUE_9046', '', 'Dia sudah membuka tas kecilnya sebelum aku sempat bilang apa-apa, lalu mengeluarkan kotak plester berwarna pastel.', 'Assets/Character/Edelweiss/Edelweiss.png', 9047, 0, 0, 0, 0, 10),
(9047, 9047, 'D_PROLOGUE_9047', 'Edelweiss', 'Sini deh, aku bawa plester yang lebih bagus. Ada motifnya lho. Pakai ini aja.', 'Assets/Character/Edelweiss/Edelweiss.png', 9048, 0, 2, 0, 0, 10),
(9048, 9048, 'D_PROLOGUE_9048', '', 'Ada sesuatu dalam caranya menyodorkan kotak itu yang terasa tulus, bukan sekadar basa-basi tugas jemput mahasiswa baru. Untuk sesaat aku hampir menerimanya begitu saja.', 'Assets/Character/Edelweiss/Edelweiss.png', 9049, 0, 0, 0, 0, 10),
(9049, 9049, 'D_PROLOGUE_9049', '', 'Tapi tanganku sudah lebih dulu menempelkan plester lamaku kembali, sebelum aku sempat memutuskan apa-apa.', 'Assets/Character/Edelweiss/Edelweiss.png', 9050, 0, 0, 0, 0, 10),
(9050, 9050, 'D_PROLOGUE_9050', 'Pilihan', 'Penolakan', 'Assets/Character/Edelweiss/Edelweiss.png', 0, 1, 0, 0, 0, 10),
(9051, 9051, 'D_PROLOGUE_9051', '', 'Sedetik kemudian dia sudah tersenyum lagi, mengingatkanku soal jam malam, lalu melambai dan berjalan keluar lobi dengan langkah cepatnya yang tadi.', 'Assets/Character/Edelweiss/Edelweiss.png', 9052, 0, 0, 0, 0, 10),
(9052, 9052, 'D_PROLOGUE_9052', '', 'Tapi ada satu hal yang tetap kutangkap. Sepersekian detik sebelum senyum itu kembali, ada jeda yang tidak seharusnya ada di sana.', '', 9053, 0, 0, 0, 0, 10),
(9053, 9053, 'D_PROLOGUE_9053', '', 'Aku tidak tahu itu apa. Mungkin cuma capek. Aku mengangkat koper ke anak tangga pertama dan mulai naik sendirian.', '', 9054, 0, 0, 0, 0, 10),
(9054, 9054, 'D_PROLOGUE_9054', '', 'Kamar asramaku kosong dan rapi, seperti belum pernah dipakai siapa pun. Mungkin memang belum. Koperku belum kubongkar. Aku duduk di tepi ranjang dengan tas kamera masih tergantung di bahu, terlalu capek bahkan untuk melepasnya.', '', 9055, 0, 0, 0, 0, 10),
(9055, 9055, 'D_PROLOGUE_9055', '', 'Dari jendela, lampu koridor gedung sebelah masih menyala satu-satu, sama seperti tadi sore. Bedanya, langit di belakangnya sekarang sudah gelap total.', '', 9056, 0, 0, 0, 0, 10),
(9056, 9056, 'D_PROLOGUE_9056', '', 'Hari ini aku belajar satu aturan. Cara menyampaikan kesalahan orang tanpa membuatnya kehilangan muka. Aturan itu bisa dijelaskan dalam tiga kalimat di kaki tangga.', '', 9057, 0, 0, 0, 0, 10),
(9057, 9057, 'D_PROLOGUE_9057', '', 'Tapi jeda di senyum Edelweiss tadi, aku tidak tahu itu aturan yang mana.', '', 9058, 0, 0, 0, 0, 10),
(9058, 9058, 'D_PROLOGUE_9058', '', 'Aku melepas tas kamera, meletakkannya di meja, dan berbaring tanpa mengganti baju. Besok hari pertama yang sesungguhnya.', '', 9059, 0, 0, 0, 0, 10),
(9059, 9059, 'D_PROLOGUE_9059', '', 'Hal terakhir yang terlintas sebelum aku tertidur bukan gerbang kampus, bukan kamar baru ini, tapi jeda kecil itu. Yang tidak sempat selesai kupikirkan.', '', 0, 0, 0, 0, 0, 10),
(9060, 9060, 'D_PROLOGUE_9060', 'Devano', 'Iya, aku Devano. Kamu yang jemput aku, ya?', '', 9061, 0, 0, 0, 0, 10),
(9061, 9061, 'D_PROLOGUE_9061', 'Edelweiss', 'Iya! Aku Edelweiss. Dosen bilang aku yang jemput kamu hari ini.', 'Assets/Character/Edelweiss/Edelweiss.png', 9062, 0, 2, 0, 0, 10),
(9062, 9062, 'D_PROLOGUE_9062', '', 'Bahunya turun sedikit. Lega, seperti barusan lolos ujian kecil yang cuma dia sendiri yang tahu.', 'Assets/Character/Edelweiss/Edelweiss.png', 9012, 0, 0, 0, 0, 10),
(9063, 9063, 'D_PROLOGUE_9063', 'Devano', 'Betul. Devano Baskara Pratama, peserta program pertukaran.', '', 9064, 0, 0, 0, 0, 10),
(9064, 9064, 'D_PROLOGUE_9064', '', 'Dia ikut menegakkan punggung, seolah sedang berhadapan dengan dosen, lalu sadar sendiri dan buru-buru menurunkan bahunya lagi.', 'Assets/Character/Edelweiss/Edelweiss.png', 9065, 0, 0, 0, 0, 10),
(9065, 9065, 'D_PROLOGUE_9065', 'Edelweiss', 'Eh, iya, iya. Aku Edelweiss. Santai aja kali, aku bukan dosen kok.', 'Assets/Character/Edelweiss/Edelweiss.png', 9012, 0, 2, 0, 0, 10),
(9066, 9066, 'D_PROLOGUE_9066', 'Devano', 'Iya. Yang kopernya barusan nyangkut di ubin itu.', '', 9067, 0, 0, 0, 0, 10),
(9067, 9067, 'D_PROLOGUE_9067', '', 'Dia melirik koperku, lalu ubinnya, lalu tertawa. Agak keras, dan sedikit kelamaan.', 'Assets/Character/Edelweiss/Edelweiss.png', 9068, 0, 0, 0, 0, 10),
(9068, 9068, 'D_PROLOGUE_9068', 'Edelweiss', 'Ubin di sini emang jahat. Aku Edelweiss, yang ditugasin jemput kamu.', 'Assets/Character/Edelweiss/Edelweiss.png', 9012, 0, 2, 0, 0, 10),
(9069, 9069, 'D_PROLOGUE_9069', 'Devano', 'Makasih. Dari pagi aku belum sempat makan apa-apa, sih.', '', 9070, 0, 0, 0, 0, 10),
(9070, 9070, 'D_PROLOGUE_9070', 'Edelweiss', 'Hah, serius?! Ih, nanti kutunjukin kantin yang buka sampai malam.', 'Assets/Character/Edelweiss/Edelweiss.png', 9071, 0, 2, 0, 0, 10),
(9071, 9071, 'D_PROLOGUE_9071', '', 'Nada suaranya langsung berubah cepat, seperti baru dapat tugas tambahan yang harus segera diurus.', 'Assets/Character/Edelweiss/Edelweiss.png', 9017, 0, 0, 0, 0, 10),
(9072, 9072, 'D_PROLOGUE_9072', 'Devano', 'Oh. Jadi aku bukan spesial, ya.', '', 9073, 0, 0, 0, 0, 10),
(9073, 9073, 'D_PROLOGUE_9073', 'Edelweiss', 'Bukan gitu maksudnya! Maksudku, ya, bukan berarti… aduh.', 'Assets/Character/Edelweiss/Edelweiss.png', 9074, 0, 2, 0, 0, 10),
(9074, 9074, 'D_PROLOGUE_9074', '', 'Merahnya merambat sampai ke telinga. Dia menatap permen di tanganku seolah permen itu yang salah.', 'Assets/Character/Edelweiss/Edelweiss.png', 9075, 0, 0, 0, 0, 10),
(9075, 9075, 'D_PROLOGUE_9075', 'Edelweiss', 'Pokoknya terima aja!', 'Assets/Character/Edelweiss/Edelweiss.png', 9017, 0, 2, 0, 0, 10),
(9076, 9076, 'D_PROLOGUE_9076', 'Devano', 'Makasih.', '', 9077, 0, 0, 0, 0, 10),
(9077, 9077, 'D_PROLOGUE_9077', '', 'Aku memasukkannya ke saku jaket. Ada jeda kecil sebelum dia menjawab, sepersekian detik saja.', 'Assets/Character/Edelweiss/Edelweiss.png', 9078, 0, 0, 0, 0, 10),
(9078, 9078, 'D_PROLOGUE_9078', 'Edelweiss', '…Sama-sama!', 'Assets/Character/Edelweiss/Edelweiss.png', 9017, 0, 2, 0, 0, 10),
(9079, 9079, 'D_PROLOGUE_9079', 'Devano', 'Banget. Aku udah nyiapin daftar tempat yang mau kufoto.', '', 9080, 0, 0, 0, 0, 10),
(9080, 9080, 'D_PROLOGUE_9080', 'Edelweiss', 'Daftar?! Kamu suka foto? Coba nanti kulihat daftarnya, siapa tahu ada yang salah tempat.', 'Assets/Character/Edelweiss/Edelweiss.png', 9081, 0, 2, 0, 0, 10),
(9081, 9081, 'D_PROLOGUE_9081', '', 'Dia mengatakannya dengan nada orang yang sudah lama tinggal di sini, dan kelihatan agak bangga dengan nada itu.', 'Assets/Character/Edelweiss/Edelweiss.png', 9025, 0, 0, 0, 0, 10),
(9082, 9082, 'D_PROLOGUE_9082', 'Devano', 'Jujur, lebih ke deg-degan, sih. Belum kebayang apa-apa.', '', 9083, 0, 0, 0, 0, 10),
(9083, 9083, 'D_PROLOGUE_9083', '', 'Dia diam sebentar. Lalu suaranya turun setengah nada.', 'Assets/Character/Edelweiss/Edelweiss.png', 9084, 0, 0, 0, 0, 10),
(9084, 9084, 'D_PROLOGUE_9084', 'Edelweiss', 'Wajar kok. Aku dulu nangis di minggu pertama.', 'Assets/Character/Edelweiss/Edelweiss.png', 9085, 0, 2, 0, 0, 10),
(9085, 9085, 'D_PROLOGUE_9085', '', 'Cepat-cepat, seperti menyesal sudah bilang:', 'Assets/Character/Edelweiss/Edelweiss.png', 9086, 0, 0, 0, 0, 10),
(9086, 9086, 'D_PROLOGUE_9086', 'Edelweiss', 'Tapi cuma sekali! Abis itu udah nggak. Eh, itu tas kamera, ya? Kamu suka foto?', 'Assets/Character/Edelweiss/Edelweiss.png', 9025, 0, 2, 0, 0, 10),
(9087, 9087, 'D_PROLOGUE_9087', 'Devano', 'Lumayan.', '', 9088, 0, 0, 0, 0, 10),
(9088, 9088, 'D_PROLOGUE_9088', 'Edelweiss', 'Lumayan…', 'Assets/Character/Edelweiss/Edelweiss.png', 9089, 0, 2, 0, 0, 10),
(9089, 9089, 'D_PROLOGUE_9089', '', 'Dia mengulang kata itu pelan, seperti sedang menimbang apakah jawabannya perlu dikejar. Lalu matanya jatuh ke tas di bahuku.', 'Assets/Character/Edelweiss/Edelweiss.png', 9090, 0, 0, 0, 0, 10),
(9090, 9090, 'D_PROLOGUE_9090', 'Edelweiss', 'Eh, itu tas kamera? Kamu suka foto?', 'Assets/Character/Edelweiss/Edelweiss.png', 9025, 0, 2, 0, 0, 10),
(9091, 9091, 'D_PROLOGUE_9091', '', 'Aku mengetuk kertas konfirmasi di meja.', '', 9092, 0, 0, 0, 0, 10),
(9092, 9092, 'D_PROLOGUE_9092', 'Devano', '不对。五零三。
<size=80%><i>Bú duì. Wǔ líng sān. — "Salah. Lima-nol-tiga."</i></size>', '', 9093, 0, 0, 0, 0, 10),
(9093, 9093, 'D_PROLOGUE_9093', '', 'Suaraku keluar lebih keras dari yang kurencanakan. Aku cuma ingin jelas.', '', 9094, 0, 0, 0, 0, 10),
(9094, 9094, 'D_PROLOGUE_9094', '', 'Āyí menatap kertasku, lalu melirik sebentar ke antrean di belakangku. Bibirnya merapat jadi garis tipis.', '', 9095, 0, 0, 0, 0, 10),
(9095, 9095, 'D_PROLOGUE_9095', 'Āyí', '……知道了。
<size=80%><i>Zhīdào le. — "…Iya, tahu."</i></size>', '', 9096, 0, 0, 0, 0, 10),
(9096, 9096, 'D_PROLOGUE_9096', '', 'Dia menukar kuncinya tanpa melihat ke arahku lagi, lalu langsung memanggil orang berikutnya.', '', 9097, 0, 0, 0, 0, 10),
(9097, 9097, 'D_PROLOGUE_9097', '', 'Edelweiss menarik ujung lengan jaketku, mengajakku menjauh dari meja sampai ke dekat tangga, cukup jauh sampai suara antrean tinggal dengung.', 'Assets/Character/Edelweiss/Edelweiss.png', 9098, 0, 0, 0, 0, 10),
(9098, 9098, 'D_PROLOGUE_9098', 'Edelweiss', 'Dev… soal kunci tadi.', 'Assets/Character/Edelweiss/Edelweiss.png', 9099, 0, 2, 0, 0, 10),
(9099, 9099, 'D_PROLOGUE_9099', '', 'Dia ragu sebentar, seperti sedang memilih kata. Tangannya memainkan ujung kuncirnya.', 'Assets/Character/Edelweiss/Edelweiss.png', 9100, 0, 0, 0, 0, 10),
(9100, 9100, 'D_PROLOGUE_9100', 'Edelweiss', 'Kamu nggak salah kok, nomornya emang kebalik. Tapi tadi di belakang kita ada antrean. Kalau kamu bilang ''salah'' di depan banyak orang, yang malu itu Āyí-nya. Di sini itu namanya <i>diū miànzi</i>. Kehilangan muka.', 'Assets/Character/Edelweiss/Edelweiss.png', 9101, 0, 2, 0, 0, 10),
(9101, 9101, 'D_PROLOGUE_9101', 'Devano', '…Aku cuma mau jelas.', '', 9102, 0, 0, 0, 0, 10),
(9102, 9102, 'D_PROLOGUE_9102', 'Edelweiss', 'Iya, aku tahu. Makanya caranya aja yang diganti. Bilang <i>bù hǎo yìsi</i> dulu, terus bikin kesannya kayak kamu yang mungkin salah lihat. Nanti dia sendiri yang nemu salahnya. Masalahnya beres, mukanya juga aman.', 'Assets/Character/Edelweiss/Edelweiss.png', 9103, 0, 2, 0, 0, 10),
(9103, 9103, 'D_PROLOGUE_9103', '', 'Dia tersenyum kecil, sedikit kikuk.', 'Assets/Character/Edelweiss/Edelweiss.png', 9104, 0, 0, 0, 0, 10),
(9104, 9104, 'D_PROLOGUE_9104', 'Edelweiss', 'Aku sengaja nunggu kita jauh dari meja dulu, lho. Kalau aku ngomongnya di sana, gantian kamu yang malu.', 'Assets/Character/Edelweiss/Edelweiss.png', 9105, 0, 2, 0, 0, 10),
(9105, 9105, 'D_PROLOGUE_9105', '', 'Aku teringat bibir Āyí yang merapat tadi. Waktu itu kukira dia cuma sibuk.', 'Assets/Character/Edelweiss/Edelweiss.png', 9039, 0, 0, 0, 0, 10),
(9106, 9106, 'D_PROLOGUE_9106', '', 'Aku tersenyum, lalu menunjukkan kertas konfirmasi pelan-pelan.', '', 9107, 0, 0, 0, 0, 10),
(9107, 9107, 'D_PROLOGUE_9107', 'Devano', '阿姨，不好意思……
<size=80%><i>Āyí, bù hǎo yìsi… — "Bu, maaf…"</i></size>', '', 9108, 0, 0, 0, 0, 10),
(9108, 9108, 'D_PROLOGUE_9108', 'Devano', '…Maybe I read it wrong?', '', 9109, 0, 0, 0, 0, 10),
(9109, 9109, 'D_PROLOGUE_9109', '', 'Kalimat Mandarinku cuma sampai situ. Sisanya kuserahkan pada kertas yang kutaruh di meja, nomornya menghadap ke dia.', '', 9110, 0, 0, 0, 0, 10),
(9110, 9110, 'D_PROLOGUE_9110', '', 'Āyí mendorong kacamatanya naik, menyipitkan mata ke kertas, lalu ke buku catatannya sendiri.', '', 9111, 0, 0, 0, 0, 10),
(9111, 9111, 'D_PROLOGUE_9111', 'Āyí', '哎呀，我写反了！
<size=80%><i>Āiyā, wǒ xiě fǎn le! — "Aduh, kebalik nulisnya!"</i></size>', '', 9112, 0, 0, 0, 0, 10),
(9112, 9112, 'D_PROLOGUE_9112', '', 'Dia tertawa, menukar kuncinya, lalu berkata sesuatu ke Edelweiss sambil menunjukku dengan dagunya.', '', 9113, 0, 0, 0, 0, 10),
(9113, 9113, 'D_PROLOGUE_9113', 'Āyí', '这小伙子挺客气的。
<size=80%><i>Zhè xiǎohuǒzi tǐng kèqi de. — "Anak muda ini sopan juga, ya."</i></size>', '', 9114, 0, 0, 0, 0, 10),
(9114, 9114, 'D_PROLOGUE_9114', '', 'Edelweiss menarik ujung lengan jaketku, mengajakku menjauh dari meja sampai ke dekat tangga, cukup jauh sampai suara antrean tinggal dengung.', 'Assets/Character/Edelweiss/Edelweiss.png', 9115, 0, 0, 0, 0, 10),
(9115, 9115, 'D_PROLOGUE_9115', 'Edelweiss', 'Dev. Tadi itu… kamu belajar dari mana?', 'Assets/Character/Edelweiss/Edelweiss.png', 9116, 0, 2, 0, 0, 10),
(9116, 9116, 'D_PROLOGUE_9116', 'Devano', 'Aplikasi. Di pesawat. Cuma kalimat itu yang aku hafal.', '', 9117, 0, 0, 0, 0, 10),
(9117, 9117, 'D_PROLOGUE_9117', 'Edelweiss', 'Serius?! Āyí sampai bilang kamu sopan, lho.', 'Assets/Character/Edelweiss/Edelweiss.png', 9118, 0, 2, 0, 0, 10),
(9118, 9118, 'D_PROLOGUE_9118', '', 'Matanya berbinar, lalu nadanya berubah sedikit serius, seperti senior yang sedang menjelaskan.', 'Assets/Character/Edelweiss/Edelweiss.png', 9119, 0, 0, 0, 0, 10),
(9119, 9119, 'D_PROLOGUE_9119', 'Edelweiss', 'Yang kamu lakuin tadi tuh pas banget. Kamu kasih dia jalan buat benerin salahnya sendiri, tanpa malu di depan antrean. Di sini itu soal <i>miànzi</i>, muka. Banyak orang baru yang langsung bilang ''salah'' gitu aja, terus bingung kenapa Āyí-nya jadi jutek sebulan.', 'Assets/Character/Edelweiss/Edelweiss.png', 9120, 0, 2, 0, 0, 10),
(9120, 9120, 'D_PROLOGUE_9120', '', 'Padahal bahasa Mandarinku cuma sampai <i>bù hǎo yìsi</i>. Sisanya kertas dan senyum.', 'Assets/Character/Edelweiss/Edelweiss.png', 9039, 0, 0, 0, 0, 10),
(9121, 9121, 'D_PROLOGUE_9121', '', 'Rasanya tidak enak mengoreksi orang yang baru kukenal tiga puluh detik. Aku mengambil kunci itu dan mulai menarik koper.', '', 9122, 0, 0, 0, 0, 10),
(9122, 9122, 'D_PROLOGUE_9122', '', 'Tapi Edelweiss sudah melirik kartu di tanganku, lalu kertas di tangan satunya. Dia maju setengah langkah.', 'Assets/Character/Edelweiss/Edelweiss.png', 9123, 0, 0, 0, 0, 10),
(9123, 9123, 'D_PROLOGUE_9123', 'Edelweiss', '阿姨，不好意思，可能是我们没说清楚……他的是五零三。
<size=80%><i>Āyí, bù hǎo yìsi, kěnéng shì wǒmen méi shuō qīngchu… tā de shì wǔ líng sān. — "Bu, maaf, mungkin kami yang kurang jelas ngomongnya… punya dia 503."</i></size>', 'Assets/Character/Edelweiss/Edelweiss.png', 9124, 0, 2, 0, 0, 10),
(9124, 9124, 'D_PROLOGUE_9124', 'Āyí', '哦哦，好好。
<size=80%><i>Ó ó, hǎo hǎo. — "Oh, oh, iya iya."</i></size>', '', 9125, 0, 0, 0, 0, 10),
(9125, 9125, 'D_PROLOGUE_9125', '', 'Kuncinya ditukar. Āyí bahkan sempat tersenyum.', '', 9126, 0, 0, 0, 0, 10),
(9126, 9126, 'D_PROLOGUE_9126', '', 'Edelweiss menarik ujung lengan jaketku, mengajakku menjauh dari meja sampai ke dekat tangga, cukup jauh sampai suara antrean tinggal dengung.', 'Assets/Character/Edelweiss/Edelweiss.png', 9127, 0, 0, 0, 0, 10),
(9127, 9127, 'D_PROLOGUE_9127', 'Edelweiss', 'Kenapa diem aja tadi?', 'Assets/Character/Edelweiss/Edelweiss.png', 9128, 0, 2, 0, 0, 10),
(9128, 9128, 'D_PROLOGUE_9128', 'Devano', 'Nggak enak. Baru kenal, masa langsung dikoreksi.', '', 9129, 0, 0, 0, 0, 10),
(9129, 9129, 'D_PROLOGUE_9129', 'Edelweiss', 'Aku ngerti, aku dulu juga gitu. Tapi kalau diem, nanti malam kamu nyasar masuk kamar orang.', 'Assets/Character/Edelweiss/Edelweiss.png', 9130, 0, 2, 0, 0, 10),
(9130, 9130, 'D_PROLOGUE_9130', '', 'Dia menghela napas kecil, lalu tersenyum.', 'Assets/Character/Edelweiss/Edelweiss.png', 9131, 0, 0, 0, 0, 10),
(9131, 9131, 'D_PROLOGUE_9131', 'Edelweiss', 'Diem itu bukan sopan, Dev. Salah tetap harus dibilang. Yang dijaga itu caranya. Tadi kamu dengar kan aku bilang ''mungkin <i>kami</i> yang kurang jelas''? Salahnya aku ambil sedikit, jadi Āyí nggak kehilangan muka di depan antrean. Di sini itu namanya jaga <i>miànzi</i>.', 'Assets/Character/Edelweiss/Edelweiss.png', 9132, 0, 2, 0, 0, 10),
(9132, 9132, 'D_PROLOGUE_9132', '', 'Aku memutar kunci 503 di jariku. Ternyata ada cara ketiga di antara diam dan menegur. Aku tidak pernah memikirkannya.', 'Assets/Character/Edelweiss/Edelweiss.png', 9039, 0, 0, 0, 0, 10),
(9133, 9133, 'D_PROLOGUE_9133', 'Devano', '(berbisik) Nomornya kebalik. Bisa tolong bilangin?', '', 9134, 0, 0, 0, 0, 10),
(9134, 9134, 'D_PROLOGUE_9134', '', 'Edelweiss mengangguk kecil, lalu maju setengah langkah dengan senyum yang sudah siap.', 'Assets/Character/Edelweiss/Edelweiss.png', 9135, 0, 0, 0, 0, 10),
(9135, 9135, 'D_PROLOGUE_9135', 'Edelweiss', '阿姨，不好意思，可能是我们没说清楚……他的是五零三。
<size=80%><i>Āyí, bù hǎo yìsi, kěnéng shì wǒmen méi shuō qīngchu… tā de shì wǔ líng sān. — "Bu, maaf, mungkin kami yang kurang jelas ngomongnya… punya dia 503."</i></size>', 'Assets/Character/Edelweiss/Edelweiss.png', 9136, 0, 2, 0, 0, 10),
(9136, 9136, 'D_PROLOGUE_9136', 'Āyí', '哦哦，好好。
<size=80%><i>Ó ó, hǎo hǎo. — "Oh, oh, iya iya."</i></size>', '', 9137, 0, 0, 0, 0, 10),
(9137, 9137, 'D_PROLOGUE_9137', '', 'Kuncinya ditukar. Āyí bahkan sempat tersenyum.', '', 9138, 0, 0, 0, 0, 10),
(9138, 9138, 'D_PROLOGUE_9138', '', 'Edelweiss menarik ujung lengan jaketku, mengajakku menjauh dari meja sampai ke dekat tangga, cukup jauh sampai suara antrean tinggal dengung.', 'Assets/Character/Edelweiss/Edelweiss.png', 9139, 0, 0, 0, 0, 10),
(9139, 9139, 'D_PROLOGUE_9139', 'Edelweiss', 'Nggak apa-apa kok minta tolong lewat aku. Di sini pakai perantara malah wajar.', 'Assets/Character/Edelweiss/Edelweiss.png', 9140, 0, 2, 0, 0, 10),
(9140, 9140, 'D_PROLOGUE_9140', '', 'Lalu, lebih pelan:', 'Assets/Character/Edelweiss/Edelweiss.png', 9141, 0, 0, 0, 0, 10),
(9141, 9141, 'D_PROLOGUE_9141', 'Edelweiss', 'Tapi aku nggak selalu ada, ya. Jadi dengerin baik-baik caraku tadi. Aku bilang ''mungkin <i>kami</i> yang kurang jelas''. Salahnya aku ambil sedikit, jadi Āyí nggak kehilangan muka di depan antrean. Di sini itu namanya jaga <i>miànzi</i>. Besok-besok coba sendiri, mulai dari <i>bù hǎo yìsi</i>.', 'Assets/Character/Edelweiss/Edelweiss.png', 9142, 0, 2, 0, 0, 10),
(9142, 9142, 'D_PROLOGUE_9142', '', 'Aku mengangguk. Kalimat itu sudah kuhafal sejak di pesawat. Aku cuma belum tahu kalimat itu dipakai untuk apa.', 'Assets/Character/Edelweiss/Edelweiss.png', 9039, 0, 0, 0, 0, 10),
(9143, 9143, 'D_PROLOGUE_9143', 'Devano', 'Nggak apa-apa, cuma kegores dikit di bandara.', '', 9144, 0, 0, 0, 0, 10),
(9144, 9144, 'D_PROLOGUE_9144', 'Edelweiss', 'Dikit apanya, plesternya udah mau copot gitu.', 'Assets/Character/Edelweiss/Edelweiss.png', 9046, 0, 2, 0, 0, 10),
(9145, 9145, 'D_PROLOGUE_9145', 'Devano', 'Biasa. Kalau ada benda tajam dalam radius lima meter, pasti nemu aku.', '', 9146, 0, 0, 0, 0, 10),
(9146, 9146, 'D_PROLOGUE_9146', '', 'Dia tertawa, kali ini lebih lepas dari tadi.', 'Assets/Character/Edelweiss/Edelweiss.png', 9147, 0, 0, 0, 0, 10),
(9147, 9147, 'D_PROLOGUE_9147', 'Edelweiss', 'Kamu ngomongnya kayak bangga.', 'Assets/Character/Edelweiss/Edelweiss.png', 9046, 0, 2, 0, 0, 10),
(9148, 9148, 'D_PROLOGUE_9148', '', 'Aku memasukkan tangan ke saku.', 'Assets/Character/Edelweiss/Edelweiss.png', 9149, 0, 0, 0, 0, 10),
(9149, 9149, 'D_PROLOGUE_9149', 'Devano', 'Bukan apa-apa. Lantai lima lewat sini, kan?', '', 9150, 0, 0, 0, 0, 10),
(9150, 9150, 'D_PROLOGUE_9150', 'Edelweiss', 'Eh, jangan disembunyiin, sini—', 'Assets/Character/Edelweiss/Edelweiss.png', 9151, 0, 2, 0, 0, 10),
(9151, 9151, 'D_PROLOGUE_9151', '', 'Nadanya sempat setengah memerintah, lalu dia sendiri kaget dan buru-buru melunak.', 'Assets/Character/Edelweiss/Edelweiss.png', 9152, 0, 0, 0, 0, 10),
(9152, 9152, 'D_PROLOGUE_9152', 'Edelweiss', '…Maksudku, boleh lihat nggak?', 'Assets/Character/Edelweiss/Edelweiss.png', 9046, 0, 2, 0, 0, 10),
(9153, 9153, 'D_PROLOGUE_9153', 'Devano', 'Nggak usah, makasih ya. Aku bawa sendiri kok di tas.', '', 9154, 0, 0, 0, 0, 10),
(9154, 9154, 'D_PROLOGUE_9154', 'Edelweiss', 'Oh.', 'Assets/Character/Edelweiss/Edelweiss.png', 9155, 0, 2, 0, 0, 10),
(9155, 9155, 'D_PROLOGUE_9155', '', 'Dia menutup kotak plesternya.', 'Assets/Character/Edelweiss/Edelweiss.png', 9156, 0, 0, 0, 0, 10),
(9156, 9156, 'D_PROLOGUE_9156', 'Edelweiss', 'Oke deh kalau gitu.', 'Assets/Character/Edelweiss/Edelweiss.png', 9051, 0, 2, 0, 0, 10),
(9157, 9157, 'D_PROLOGUE_9157', 'Devano', 'Tenang, stok plesterku lebih banyak dari apotek. Pengalaman.', '', 9158, 0, 0, 0, 0, 10),
(9158, 9158, 'D_PROLOGUE_9158', '', 'Dia tertawa. Tangannya pelan-pelan menutup kotak itu sambil tertawa.', 'Assets/Character/Edelweiss/Edelweiss.png', 9159, 0, 0, 0, 0, 10),
(9159, 9159, 'D_PROLOGUE_9159', 'Edelweiss', 'Iya, iya, Pak Apoteker.', 'Assets/Character/Edelweiss/Edelweiss.png', 9051, 0, 2, 0, 0, 10),
(9160, 9160, 'D_PROLOGUE_9160', 'Devano', 'Eh, nggak usah, nggak usah. Ngerepotin. Simpan aja buat kamu.', '', 9161, 0, 0, 0, 0, 10),
(9161, 9161, 'D_PROLOGUE_9161', 'Edelweiss', 'Nggak ngerepotin kok, aku—', 'Assets/Character/Edelweiss/Edelweiss.png', 9162, 0, 2, 0, 0, 10),
(9162, 9162, 'D_PROLOGUE_9162', '', 'Kalimatnya berhenti di tengah. Dia menutup kotaknya.', 'Assets/Character/Edelweiss/Edelweiss.png', 9163, 0, 0, 0, 0, 10),
(9163, 9163, 'D_PROLOGUE_9163', 'Edelweiss', '…Oke.', 'Assets/Character/Edelweiss/Edelweiss.png', 9051, 0, 2, 0, 0, 10);
INSERT INTO tbl_dialogue_options (option_id, dialogue_id, node_id, option_text, next_dialogue_id, next_node_id, set_flag_key, set_flag_name, set_flag_value, set_flag_val) VALUES
(9001, 9011, 9011, '[Ramah] "Iya, aku Devano. Kamu yang jemput aku, ya?"', 9060, 9060, 'd0_sapa_ramah', 'd0_sapa_ramah', 1, 1),
(9002, 9011, 9011, '[Formal] "Betul. Devano Baskara Pratama, peserta program pertukaran."', 9063, 9063, 'd0_sapa_formal', 'd0_sapa_formal', 1, 1),
(9003, 9011, 9011, '[Bercanda] "Iya. Yang kopernya barusan nyangkut di ubin itu."', 9066, 9066, 'd0_sapa_canda', 'd0_sapa_canda', 1, 1),
(9004, 9016, 9016, '[Tulus] "Makasih. Dari pagi aku belum sempat makan apa-apa, sih."', 9069, 9069, 'd0_permen_tulus', 'd0_permen_tulus', 1, 1),
(9005, 9016, 9016, '[Menggoda] "Oh. Jadi aku bukan spesial, ya."', 9072, 9072, 'd0_permen_goda', 'd0_permen_goda', 1, 1),
(9006, 9016, 9016, '[Singkat] "Makasih."', 9076, 9076, 'd0_permen_singkat', 'd0_permen_singkat', 1, 1),
(9007, 9024, 9024, '[Antusias] "Banget. Aku udah nyiapin daftar tempat yang mau kufoto."', 9079, 9079, 'd0_excited_antusias', 'd0_excited_antusias', 1, 1),
(9008, 9024, 9024, '[Jujur] "Jujur, lebih ke deg-degan, sih. Belum kebayang apa-apa."', 9082, 9082, 'd0_excited_jujur', 'd0_excited_jujur', 1, 1),
(9009, 9024, 9024, '[Datar] "Lumayan."', 9087, 9087, 'd0_excited_datar', 'd0_excited_datar', 1, 1),
(9010, 9038, 9038, '[Lugas] Ketuk kertas konfirmasi di meja. "不对。五零三。" (Bú duì. Wǔ líng sān.)', 9091, 9091, 'd0_reg_lugas', 'd0_reg_lugas', 1, 1),
(9011, 9038, 9038, '[Memberi muka] Senyum, tunjukkan kertas pelan-pelan. "阿姨，不好意思……" (Āyí, bù hǎo yìsi…)', 9106, 9106, 'd0_reg_beri_muka', 'd0_reg_beri_muka', 1, 1),
(9012, 9038, 9038, '[Diam] Ambil kunci 305 tanpa berkata apa-apa. Urusannya nanti saja.', 9121, 9121, 'd0_reg_diam', 'd0_reg_diam', 1, 1),
(9013, 9038, 9038, '[Lewat perantara] Bisikkan ke Edelweiss: "Nomornya kebalik. Bisa tolong bilangin?"', 9133, 9133, 'd0_reg_perantara', 'd0_reg_perantara', 1, 1),
(9014, 9045, 9045, '[Santai] "Nggak apa-apa, cuma kegores dikit di bandara."', 9143, 9143, 'd0_luka_santai', 'd0_luka_santai', 1, 1),
(9015, 9045, 9045, '[Pasrah-lucu] "Biasa. Kalau ada benda tajam dalam radius lima meter, pasti nemu aku."', 9145, 9145, 'd0_luka_lucu', 'd0_luka_lucu', 1, 1),
(9016, 9045, 9045, '[Mengalihkan] Masukkan tangan ke saku. "Bukan apa-apa. Lantai lima lewat sini, kan?"', 9148, 9148, 'd0_luka_alih', 'd0_luka_alih', 1, 1),
(9017, 9050, 9050, '[Sopan] "Nggak usah, makasih ya. Aku bawa sendiri kok di tas."', 9153, 9153, 'd0_tolak_sopan', 'd0_tolak_sopan', 1, 1),
(9018, 9050, 9050, '[Bercanda] "Tenang, stok plesterku lebih banyak dari apotek. Pengalaman."', 9157, 9157, 'd0_tolak_canda', 'd0_tolak_canda', 1, 1),
(9019, 9050, 9050, '[Sungkan] "Eh, nggak usah, nggak usah. Ngerepotin. Simpan aja buat kamu."', 9160, 9160, 'd0_tolak_sungkan', 'd0_tolak_sungkan', 1, 1);
